        if (dados.subtotalProdutos().compareTo(MINIMO) < 0) {
            throw new CheckoutException(ErroCheckout.CUPOM_NAO_APLICAVEL);
        }
    }

    @Override
    public BigDecimal desconto(DadosCupom dados) {
        return Dinheiro.centavos(VALOR);
    }
}

